    {
      id: 2,
      label: "DogeFake",
      ticker: 'DFAKE',
      address: NEW_DOGEFAKE_ADDRESS,
      balance: 0,
      pairs: [
        {
            label: "ArbiFake",
            ticker: 'AFAKE',
            address: NEW_ARBIFAKE_ADDRESS,
        }
      ],
    }
  ];

